const JAHANGIR_INFO={id:"jahangir-zodiac-coins",title:"Emperor Jahangir's Zodiac Coinage",ruler:"Nuru'd-din Muhammad Jahangir (4th Mughal Emperor)",reignPeriod:"1605 – 1627 CE (1014–1037 AH)",issuePeriod:"1618 – 1625 CE (1027–1034 AH, Regnal Years 13 to 19)",primaryMints:"Agra, Ahmedabad, Lahore, Kashmir, Ajmer",metals:"Gold Mohur (10.9 grams) & Silver Rupee (11.4 grams)",significance:"Only Islamic coinage series in history featuring explicit astrological living figures representing the month of minting.",quickStats:[{label:"Zodiac Signs",value:"12 Signs",icon:"♈"},{label:"Mule Period",value:"1618–1625 CE",icon:"📅"},{label:"Primary Mint",value:"Agra Mint",icon:"🏛️"},{label:"Metals",value:"Gold & Silver",icon:"🪙"},{label:"Script",value:"Persian Nasta'liq",icon:"✍️"},{label:"Patronage",value:"Empress Nur Jahan",icon:"👑"}]},ZODIAC_SIGNS=[{id:"aries",name:"Aries (Haml / The Ram)",month:"Farwardin (March–April)",symbol:"♈ Ram facing right or left against rising sun background",metal:"Gold Mohur & Silver Rupee",mint:"Agra (1028 AH / RY 13)",obverseDescription:"Energetic ram crouching with sunburst rays beaming behind its back.",reverseInscription:"Yaft dar Agra rui zar zewar / Az Jahangir Shah Akbar Shah (In Agra the face of gold received ornament from Jahangir Shah, son of Akbar Shah)",history:"Issued at the start of the Persian New Year (Nowruz), celebrating renewal and royal glory."},{id:"taurus",name:"Taurus (Saur / The Bull)",month:"Urdibihisht (April–May)",symbol:"♉ Powerful humped Zebu bull standing or reclining",metal:"Gold Mohur & Silver Rupee",mint:"Agra & Ahmedabad (1028 AH / RY 14)",obverseDescription:"Indian humped bull with curved horns and radiant sun halos.",reverseInscription:"Zar Agra Shud Zewar-i-Jahangiri / Shah Akbar Shah Jahangir Shah",history:"Reflects Jahangir's admiration for native Indian fauna and royal strength."},{id:"gemini",name:"Gemini (Jauza / The Twins)",month:"Khurdad (May–June)",symbol:"♊ Twin figures embraced or holding hands",metal:"Gold Mohur",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Two male figures or youth and maiden embracing, wearing Persian court robes.",reverseInscription:"Sikka-i-Agra Zewar-i-Jahangir / Shah Akbar Shah Jahangir Shah",history:"A bold departure from traditional iconoclasm, showcasing human figures on imperial money."},{id:"cancer",name:"Cancer (Saratan / The Crab)",month:"Tir (June–July)",symbol:"♋ Crab beneath sun disc",metal:"Gold Mohur & Silver Rupee",mint:"Agra & Ahmedabad (1027 AH / RY 13)",obverseDescription:"Crab positioned horizontally in center of field with sunburst above.",reverseInscription:"Zar Ahmedabad Shud Zewar-i-Jahangir / Shah Akbar Shah Jahangir Shah",history:"Minted during Jahangir's famous stay in Ahmedabad, Gujarat."},{id:"leo",name:"Leo (Asad / The Lion)",month:"Amardad (July–August)",symbol:"♌ Lion with solar rays radiating from back",metal:"Gold Mohur & Silver Rupee",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Proud lion walking left with full radiant sun rising behind its body.",reverseInscription:"Yaft dar Agra rui zar zewar / Az Jahangir Shah Akbar Shah",history:"Leo was Jahangir's personal birth sign, making Asad Mohurs among the most prized in imperial history."},{id:"virgo",name:"Virgo (Sunbula / The Maiden)",month:"Shahriwar (August–September)",symbol:"♍ Maiden holding ears of wheat",metal:"Gold Mohur",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Young maiden in Mughal attire holding a sheaf of corn/wheat in her right hand.",reverseInscription:"Sikka-i-Agra Zewar-i-Jahangiri / Jahangir Shah Ibn Akbar Shah",history:"Symbolizing harvest abundance and fertility across the Mughal heartland."},{id:"libra",name:"Libra (Mizan / The Scales)",month:"Mihr (September–October)",symbol:"♎ Balance scales with equal pans",metal:"Gold Mohur & Silver Rupee",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Two-pan balance scales suspended from a central ring, symbolizing justice.",reverseInscription:"Zar Agra Shud Zewar-i-Jahangir / Shah Akbar Shah Jahangir Shah",history:"Directly linked to Jahangir's famous 'Chain of Justice' (Zanjir-i-Adl) hung outside Agra Fort."},{id:"scorpio",name:"Scorpio (Aqrab / The Scorpion)",month:"Aban (October–November)",symbol:"♏ Scorpion with curled tail",metal:"Gold Mohur",mint:"Agra (1029 AH / RY 15)",obverseDescription:"Segmented scorpion with curved venomous tail encircled by sunburst.",reverseInscription:"Yaft dar Agra rui zar zewar / Az Jahangir Shah Akbar Shah",history:"Depicts the scorpion emblem with remarkable zoological accuracy."},{id:"sagittarius",name:"Sagittarius (Qaus / The Archer)",month:"Azar (November–December)",symbol:"♐ Centaur archer drawing bow",metal:"Gold Mohur",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Centaur turning backward with drawn bow shooting arrow toward dragon tail.",reverseInscription:"Sikka-i-Agra Zewar-i-Jahangiri / Shah Akbar Shah Jahangir Shah",history:"Blends Hellenistic and Persian astrological iconography."},{id:"capricorn",name:"Capricorn (Jaddi / The Sea-Goat)",month:"Dai (December–January)",symbol:"♑ Goat forequarters with fish tail",metal:"Gold Mohur",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Mythical sea-goat with horns and curled aquatic tail.",reverseInscription:"Zar Agra Shud Zewar-i-Jahangir / Shah Akbar Shah Jahangir Shah",history:"Representing winter solstice transition in the Persian solar calendar."},{id:"aquarius",name:"Aquarius (Dalu / The Water Bearer)",month:"Bahman (January–February)",symbol:"♒ Water jug spilling water stream",metal:"Gold Mohur",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Traditional Indian water vessel (lota) pouring water stream.",reverseInscription:"Yaft dar Agra rui zar zewar / Az Jahangir Shah Akbar Shah",history:"Symbolizing life-giving rains and cosmic purity."},{id:"pisces",name:"Pisces (Hut / The Fishes)",month:"Isfandarmad (February–March)",symbol:"♓ Two fish swimming in opposite directions",metal:"Gold Mohur & Silver Rupee",mint:"Agra (1028 AH / RY 14)",obverseDescription:"Twin fish curved around a central lotus rosette.",reverseInscription:"Zar Agra Shud Zewar-i-Jahangir / Shah Akbar Shah Jahangir Shah",history:"Completes the 12-month solar cycle before Nowruz."}],TIMELINE_EVENTS=[{year:"1618 CE (1027 AH)",title:"Conception of Zodiac Series",description:"Jahangir records in his memoirs (Tuzuk-i-Jahangiri) that instead of plain text, coins should bear the sign of the Zodiac corresponding to the month of issue."},{year:"1619–1623 CE",title:"Agra & Ahmedabad Peak Minting",description:"Master die-engravers in Agra and Ahmedabad produce brilliant gold Mohurs and silver Rupees under Empress Nur Jahan's patronage."},{year:"1627 CE",title:"Death of Jahangir",description:"Production halts upon Jahangir's death in Kashmir; coins become instant collectors' treasures across Europe and Asia."},{year:"1628 CE",title:"Shah Jahan Melt Decree",description:"Orthodox Emperor Shah Jahan orders all Zodiac coins surrendered and melted into standard bullion; remaining specimens become extremely rare."}],REFERENCES=[{text:"Jahangir, Emperor (1624). Tuzuk-i-Jahangiri (Memoirs of Jahangir). Trans. Alexander Rogers.",link:"#"},{text:"Bhandare, Shailendra (2015). Zodiac Coins of Jahangir. Ashmolean Museum, Oxford.",link:"#"},{text:"Whitehead, R. B. (1914). Catalogue of Coins in the Panjab Museum, Lahore: Vol. II Mughal Emperors. Clarendon Press.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={JAHANGIR_INFO:JAHANGIR_INFO,ZODIAC_SIGNS:ZODIAC_SIGNS,TIMELINE_EVENTS:TIMELINE_EVENTS,REFERENCES:REFERENCES});